#!/usr/bin/env bash
# Builds scuffed_perms/roles/all.txt: every Scuffed role list in one file, so the
# world downloads all roles with ONE string load (VRChat only does one every 5 s).
#
# Each list becomes a section headed "### FILE: <file name>". The world matches a
# role to its section by the last part of that role's own link (e.g. devs.txt,
# "Com Lead"). scuffed_perms/perms.js builds the exact same file when it saves,
# so keep the two in step if you change the format.
set -euo pipefail
cd "$(dirname "$0")/../.."
export LC_ALL=C   # byte-order file sorting, same as the editor page

dir=scuffed_perms/roles
out=$dir/all.txt
tmp=$(mktemp)
{
  echo "# AUTO-GENERATED - do not edit this file."
  echo "# Built from the other files in $dir/ (kanaris-beans.com/scuffed_perms/ or .github/workflows/combine-scuffed-perms.yml)."
  echo "# Edit the individual role files instead."
  for f in "$dir"/*; do
    name=$(basename "$f")
    [ -f "$f" ] || continue
    [ "$name" = "all.txt" ] && continue
    echo
    echo "### FILE: $name"
    # Drop CRs and blank lines; make sure the last name ends with a newline.
    tr -d '\r' < "$f" | sed -e '/^[[:space:]]*$/d' -e '$a\'
  done
} > "$tmp"
mv "$tmp" "$out"
echo "Wrote $out"
